pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testRegression_property() public {
        address nonOwner = address(1);
        vm.prank(nonOwner);
        bool ok;
        try c.transferOwnership(address(2)) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok);
    }
}
